<script setup>
import {dramaCategoryStyle} from './categoryColors.js';
import {calendarAction,visibleEventCount} from '../utils/calendarDisplay.js';
import {dramaTypes} from './schedule.js';
import CalendarMonthBar from '../components/CalendarMonthBar.vue';
import {dramaImages} from './images.js';
import DramaImageGallery from './DramaImageGallery.vue';
import CalendarSectionHeading from '../components/CalendarSectionHeading.vue';
import {resolvePlatformLogo,matchedPlatform} from './platforms.js';
const platformLogo=p=>resolvePlatformLogo(p,import.meta.env.BASE_URL);
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import DramaSubmission from './DramaSubmission.vue';
import {initialData} from './seed.js';
import {generateSchedule,dramaTitle,announcementsForEpisode} from './schedule.js';
const submissionOpen=ref(false);
const key='chob-drama-private-v1';
let saved;try{saved=JSON.parse(localStorage.getItem(key));}catch{}
const props=defineProps({embedded:Boolean,scheduleArtists:{type:Array,default:()=>[]},loadSnapshot:{type:Function,default:null}});
const db=ref(props.loadSnapshot?{dramas:[],changes:[],events:[],platforms:[],artists:[]}:saved?.dramas && saved?.platforms && saved?.events && saved?.changes && saved?.artists?saved:structuredClone(initialData));
const storageError=ref('');
let polling;async function refresh(){try{if(props.loadSnapshot){db.value=await props.loadSnapshot();}else{const response=await fetch('/__drama_test_data');if(!response.ok)throw Error('测试数据读取失败');db.value=await response.json();}storageError.value='';}catch(e){storageError.value=e.message;}}onMounted(()=>{refresh();polling=setInterval(refresh,props.loadSnapshot?30000:2000);});onBeforeUnmount(()=>clearInterval(polling));


const tab=ref('calendar'),month=ref('2026-11'),search=ref(''),selected=ref(null),error=ref(''),notice=ref(''),eventSelected=ref(null),unused=ref(null);

const selectedCalendarDate=ref('');
const agendaDate=computed(()=>selectedCalendarDate.value.startsWith(month.value)?selectedCalendarDate.value:slots.value.find(s=>s.date.startsWith(month.value))?.date||month.value+'-01');
const title=dramaTitle;
function safe(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const companyFilter=ref([]),typeFilter=ref([]),calendarMode=ref('month'),weekAnchor=ref(''),dayDialog=ref(''),dayType=ref('all');
const typeLabel=t=>({'Boys Love':'BL','Girls Love':'GL'}[t]||t);
const companies=computed(()=>[...new Set(db.value.dramas.map(d=>d.productionCompany).filter(Boolean))].sort());
const matchesFilters=d=>(!companyFilter.value.length||companyFilter.value.includes(d.productionCompany))&&(!typeFilter.value.length||d.types.some(t=>typeFilter.value.includes(t)));
const filtered=computed(()=>db.value.dramas.filter(matchesFilters).filter(d=>[d.titleZh,d.titleEn,d.titleTh,...d.types].join(' ').toLowerCase().includes(search.value.toLowerCase())));
const slots=computed(()=>{const out=[];for(const d of db.value.dramas)for(const r of d.rules){let rows=generateSchedule(d,r);for(const c of db.value.changes.filter(c=>c.original.dramaId===d.id&&c.original.ruleId===r.id)){rows=rows.map(s=>s.id===c.original.id?c.original:s);rows.push(c.replacement);}if(matchesFilters(d))out.push(...rows);}return out;});
const days=computed(()=>{if(!month.value)return [];if(calendarMode.value==='week'){const start=new Date((weekAnchor.value||month.value+'-01')+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-start.getUTCDay());return Array.from({length:7},(_,i)=>new Date(+start+i*86400000).toISOString().slice(0,10));}const start=new Date(month.value+'-01T00:00:00Z');const count=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();return [...Array(start.getUTCDay()).fill(null),...Array.from({length:count},(_,i)=>`${month.value}-${String(i+1).padStart(2,'0')}`)];});
const notices=computed(()=>selected.value?.slot?announcementsForEpisode(db.value.changes.map(c=>c.announcement),selected.value.drama.id,selected.value.slot.episode):db.value.changes.filter(c=>c.announcement.dramaId===selected.value?.drama.id).map(c=>c.announcement));
function drama(id){return db.value.dramas.find(d=>d.id===id);}
function platform(id){return db.value.platforms.find(p=>p.id===id)||{name:id};}
function status(d){const rows=slots.value.filter(s=>s.dramaId===d.id&&s.status!=='changed');if(!rows.length)return d.production;if(rows.every(s=>s.date<new Date().toISOString().slice(0,10)))return '已完播';return rows.some(s=>s.date<=new Date().toISOString().slice(0,10))?'播出中':'待播';}
function open(d,slot=null){selected.value={drama:d,slot};}
const chineseMonths=['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'];
const englishMonths=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function shiftMonth(n){if(calendarMode.value==='week'){const d=new Date((weekAnchor.value||month.value+'-01')+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n*7);weekAnchor.value=d.toISOString().slice(0,10);month.value=weekAnchor.value.slice(0,7);return;}const d=new Date(month.value+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);month.value=d.toISOString().slice(0,7);}
const stats=computed(()=>['Boys Love','Girls Love','BG','Bromance'].map(type=>({type,label:typeLabel(type),count:filtered.value.filter(d=>d.types.includes(type)).length})));
const dayRows=computed(()=>slots.value.filter(s=>s.date===dayDialog.value&&(dayType.value==='all'||drama(s.dramaId).types.includes(dayType.value))));
function showDay(day){dayDialog.value=day;dayType.value='all';selectedCalendarDate.value=day;}
function slotClick(slot){if(calendarAction(slots.value.filter(s=>s.date===slot.date).length,window.matchMedia('(max-width:700px)').matches)==='day')showDay(slot.date);else open(drama(slot.dramaId),slot);}
function limit(day){return visibleEventCount(slots.value.filter(s=>s.date===day).length,window.matchMedia('(max-width:700px)').matches);}
function toggleChoice(target,value,options){const current=target==='company'?companyFilter:typeFilter;const values=new Set(current.value.length?current.value.filter(value=>value!=='__none__'):options);values.has(value)?values.delete(value):values.add(value);current.value=values.size===options.length?[]:values.size?[...values]:['__none__'];}
function today(){const key=new Date().toISOString().slice(0,10);month.value=key.slice(0,7);weekAnchor.value=key;}
</script>
<template>
<div class="shell"><header v-if="!embedded"><a class="brand" href="#">CHOB<span>CALENDAR</span></a><span class="private">私人测试 · 隔离数据</span></header>
<main><div class="c-drama-hero"><CalendarSectionHeading word="Drama" chinese="追剧日历" eyebrow="STORIES, ONE DAY AT A TIME" description="把每一次相遇，放进日历。" /><nav><button v-for="(label,id) in {calendar:'播出月历',library:'剧集库'}" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav></div><p v-if="loadSnapshot" class="muted">管理员私有数据库预览 · 未公开发布 <button @click="refresh">刷新资料</button></p><p v-if="storageError" role="alert">{{storageError}}</p><p v-if="notice" role="status">{{notice}}</p>
<section v-if="tab==='calendar'" class="c-drama-card"><CalendarMonthBar :month="month" :title="chineseMonths[Number(month.slice(5))-1]" :english="englishMonths[Number(month.slice(5))-1]" @previous="shiftMonth(-1)" @next="shiftMonth(1)" @today="today"><div class="drama-view-switch"><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">月</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">周</button></div></CalendarMonthBar><section class="drama-stats" aria-label="剧集类别统计"><div v-for="stat in stats" :key="stat.type" :style="dramaCategoryStyle([stat.type])"><strong>{{stat.count}}</strong><span>{{stat.label}}</span></div></section><div class="drama-filter-row"><div class="drama-mobile-view"><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">月</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">周</button></div><details v-for="kind in ['company','type']" :key="kind" class="drama-filter-menu"><summary>{{kind==='company'?'出品公司':'剧集类别'}}<span class="filter-chevron" aria-hidden="true"></span></summary><div class="drama-filter-options"><div><button @click="kind==='company'?companyFilter=[]:typeFilter=[]">全选</button><button @click="kind==='company'?companyFilter=['__none__']:typeFilter=['__none__']">全不选</button></div><label v-for="option in kind==='company'?companies:dramaTypes" :key="option"><input type="checkbox" :checked="!(kind==='company'?companyFilter:typeFilter).length||(kind==='company'?companyFilter:typeFilter).includes(option)" @change="toggleChoice(kind,option,kind==='company'?companies:dramaTypes)">{{kind==='type'?typeLabel(option):option}}</label><p v-if="kind==='company'&&!companies.length">暂无出品公司</p></div></details></div><div class="calendar" :class="{'week-calendar':calendarMode==='week'}"><b v-for="(w,i) in ['周日','周一','周二','周三','周四','周五','周六']" class="weekday" :class="{sunday:i===0,saturday:i===6}">{{w}}</b><div v-for="(day,index) in days" :key="day||index" class="day" :class="{blank:!day,sunday:day&&new Date(day+'T00:00:00Z').getUTCDay()===0,saturday:day&&new Date(day+'T00:00:00Z').getUTCDay()===6}" @click.self="day&&showDay(day)"><button v-if="day" class="day-number" :aria-label="day" :aria-pressed="agendaDate===day" @click="showDay(day)">{{Number(day.slice(-2))}}</button><span v-if="day&&slots.some(s=>s.date===day)" class="mobile-day-dot" aria-label="有剧集播出"></span><template v-if="day"><button v-for="s in slots.filter(s=>s.date===day).slice(0,limit(day))" :key="s.id" class="chip" :style="dramaCategoryStyle(drama(s.dramaId).types)" :class="{changed:s.status==='changed'}" @click="slotClick(s)"><span :class="{strike:s.status==='changed'}">{{title(drama(s.dramaId))}} · EP.{{s.episode}}</span><span v-if="s.status==='changed'"> · 剧集变动</span><span class="drama-chip-type">{{drama(s.dramaId).types.map(typeLabel).join('/')}}</span></button><button v-if="slots.filter(s=>s.date===day).length>limit(day)" class="drama-more" @click="showDay(day)">还有 {{slots.filter(s=>s.date===day).length-limit(day)}} 项</button></template></div></div><div class="mobile-drama-agenda"><button v-for="s in slots.filter(s=>s.date===agendaDate)" :key="s.id" :style="dramaCategoryStyle(drama(s.dramaId).types)" :class="{changed:s.status==='changed'}" @click="slotClick(s)">{{Number(agendaDate.slice(-2))}} 日 · {{title(drama(s.dramaId))}} · EP.{{s.episode}} {{s.status==='changed'?'· 剧集变动':''}}<span class="drama-chip-type">{{drama(s.dramaId).types.map(typeLabel).join('/')}}</span></button><p v-if="!slots.some(s=>s.date===agendaDate)">{{Number(agendaDate.slice(-2))}} 日暂无播出</p></div></section>
<section v-if="tab==='library'"><div class="drama-filter-row"><div class="drama-mobile-view"><button :class="{active:calendarMode==='month'}" @click="calendarMode='month'">月</button><button :class="{active:calendarMode==='week'}" @click="calendarMode='week';weekAnchor=agendaDate">周</button></div><details v-for="kind in ['company','type']" :key="kind" class="drama-filter-menu"><summary>{{kind==='company'?'出品公司':'剧集类别'}}<span class="filter-chevron" aria-hidden="true"></span></summary><div class="drama-filter-options"><div><button @click="kind==='company'?companyFilter=[]:typeFilter=[]">全选</button><button @click="kind==='company'?companyFilter=['__none__']:typeFilter=['__none__']">全不选</button></div><label v-for="option in kind==='company'?companies:dramaTypes" :key="option"><input type="checkbox" :checked="!(kind==='company'?companyFilter:typeFilter).length||(kind==='company'?companyFilter:typeFilter).includes(option)" @change="toggleChoice(kind,option,kind==='company'?companies:dramaTypes)">{{kind==='type'?typeLabel(option):option}}</label><p v-if="kind==='company'&&!companies.length">暂无出品公司</p></div></details></div><div class="toolbar"><input v-model="search" placeholder="搜索剧名、类型" aria-label="搜索剧集"><span>{{filtered.length}} 部剧集</span></div><div class="cards"><article v-for="d in filtered" :key="d.id" class="card"><button class="card-main" @click="open(d)"><img v-if="dramaImages(d)[0]" :src="dramaImages(d)[0]" alt="剧集海报"><div v-else class="poster">CHOB<br>DRAMA</div><div><span class="badge">{{status(d)}}</span><h2>{{title(d)}}</h2><p>{{d.titleEn}}</p><p class="muted">{{d.types.join(' · ')}}</p><p>{{d.cast.map(c=>c.name).join('、')||'Cast 待公布'}}</p></div></button></article></div><p v-if="!filtered.length">暂无匹配剧集</p></section>


</main><button class="drama-add" @click="submissionOpen=true" aria-label="新增剧集" title="新增剧集">＋</button><DramaSubmission :schedule-artists="scheduleArtists" v-if="submissionOpen" @close="submissionOpen=false" />
<Teleport to="body"><div v-if="dayDialog" class="drama-day-overlay" @click.self="dayDialog=''"><section class="drama-day-dialog" role="dialog" aria-modal="true" aria-label="全天剧集" @keydown.esc="dayDialog=''"><header><div><h2>{{dayDialog}}</h2><p>全天播出</p></div><button @click="dayDialog=''" aria-label="关闭全天列表">×</button></header><p>共 {{dayRows.length}} 项播出</p><nav class="drama-day-types"><button :class="{active:dayType==='all'}" @click="dayType='all'">全部</button><button v-for="type in dramaTypes" :class="{active:dayType===type}" @click="dayType=type">{{typeLabel(type)}}</button></nav><button v-for="slot in dayRows" class="drama-day-capsule" :style="dramaCategoryStyle(drama(slot.dramaId).types)" @click="open(drama(slot.dramaId),slot)"><span :class="{strike:slot.status==='changed'}">{{title(drama(slot.dramaId))}} · EP.{{slot.episode}}</span><span class="drama-chip-type">{{drama(slot.dramaId).types.map(typeLabel).join('/')}}</span></button><p v-if="!dayRows.length">暂无符合筛选的播出</p></section></div></Teleport><div v-if="selected" class="overlay" @click.self="selected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="剧集详情" tabindex="-1" @keydown.esc="selected=null"><button class="close" @click="selected=null">关闭 ×</button><div class="hero"><div v-if="!dramaImages(selected.drama).length" class="poster-placeholder">海报待公布</div><DramaImageGallery :drama="selected.drama" /><div v-if="selected.slot?.status==='changed'" class="banner"><strong>剧集变动</strong><span>{{notices.find(n=>n.id===selected.slot.announcementId)?.content}}</span></div></div><span class="badge">{{status(selected.drama)}}</span><h2>{{title(selected.drama)}}</h2><p>{{selected.drama.types.join(' · ')}}</p><p>{{selected.drama.synopsis}}</p><p v-if="selected.drama.productionCompany">出品公司：{{selected.drama.productionCompany}}</p><h3 v-if="selected.slot">EP.{{selected.slot.episode}} · {{selected.slot.date}}</h3><p v-if="selected.slot" class="platform"><img v-if="platformLogo(platform(selected.slot.platformId))" :src="platformLogo(platform(selected.slot.platformId))" alt="">{{platform(selected.slot.platformId).name}} · {{selected.slot.time}} · {{selected.slot.timezone}} <small>{{selected.slot.confidence==='calculated'?'系统推算':'已确认'}}</small></p><aside v-for="n in notices" class="announcement"><strong>剧集变动 · EP.{{n.affectedEpisodes.join('、')}}</strong><p>{{n.content}}</p><small>原定 {{n.originalDate}} → 调整后 {{n.updatedDate}}</small></aside><h3>Cast</h3><p v-for="c in selected.drama.cast">{{c.name}} 饰 {{c.role||'待公布'}}</p><a v-if="safe(selected.drama.source)" :href="safe(selected.drama.source)" target="_blank" rel="noopener noreferrer">官方来源 ↗</a><h3>Press Tour / 观影活动</h3><button v-for="e in db.events.filter(e=>e.dramaId===selected.drama.id)" class="event-row" @click="eventSelected=e">{{e.date}} · {{e.name}} ↗ Calendar</button></section></div>
<div v-if="eventSelected" class="overlay" @click.self="eventSelected=null"><section class="dialog" role="dialog" aria-modal="true" aria-label="Calendar 活动详情"><button class="close" @click="eventSelected=null">关闭 ×</button><p class="eyebrow">CALENDAR · {{eventSelected.type}}</p><h2>{{eventSelected.name}}</h2><p>{{eventSelected.date}} {{eventSelected.time}}</p><p>{{eventSelected.location}}</p><button @click="open(drama(eventSelected.dramaId));eventSelected=null">查看关联剧集 ↗</button></section></div>
<footer>CHOB CALENDAR · DRAMA V1 <span>隔离预览 / 非正式数据</span></footer></div>
</template>
<style scoped>
*{box-sizing:border-box}body{margin:0;background:#fff;color:#303b35;font:15px/1.6 system-ui,-apple-system,'Microsoft YaHei',sans-serif}button,input,select,textarea{font:inherit}button,a{cursor:pointer}button{border:1px solid #d9ded7;background:white;border-radius:8px;padding:8px 14px;color:inherit}button:hover{background:#e9eee7}input,select,textarea{border:1px solid #d9ded7;border-radius:7px;padding:9px;background:white;max-width:100%}textarea{min-height:85px}header{display:flex;gap:20px;align-items:center;padding:24px 5%;border-bottom:1px solid #e4e5dd}.brand{font-size:25px;font-weight:800;letter-spacing:3px;text-decoration:none;color:#3f5848}.brand span{display:block;font-size:9px;letter-spacing:4px}.private{margin-left:auto;font-size:12px;color:#777}main{max-width:1280px;margin:auto;padding:40px 30px}.heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-size:11px;letter-spacing:3px;color:#86927d}h1{font-size:44px;margin:8px 0;font-family:Georgia,serif}h1 em{font:normal 21px system-ui;margin-left:12px;color:#89957d}h2{font-size:23px}h3{font-size:17px}.muted,small{color:#7d857d}.primary{background:#4e664d;color:white;border-color:#4e664d}.primary:hover{background:#3c503c}nav{display:flex;gap:22px;border-bottom:1px solid #dfe3da;margin:30px 0}nav button{border:0;border-radius:0;background:none;padding:14px 4px}.active{border-bottom:3px solid #4e664d!important;font-weight:700}.toolbar{display:flex;justify-content:space-between;gap:16px;margin:20px 0}.calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-top:1px solid #e1e5dc;border-left:1px solid #e1e5dc;background:white}.weekday{text-align:center;font-weight:400;padding:12px;background:#f1f3ed}.day{min-height:150px;border-right:1px solid #e1e5dc;border-bottom:1px solid #e1e5dc;padding:8px}.blank{background:#f7f7f3}.day-number{font-size:13px;color:#8b9288}.chip{display:block;width:100%;text-align:left;padding:7px;margin:5px 0;font-size:12px;background:#edf2e9;border:0;border-left:3px solid #8ca37b;border-radius:4px}.chip small{display:block;font-size:10px}.changed{background:#f7e9e2;border-color:#c69077}.strike{text-decoration:line-through}.event{background:#f1ecf7;border-color:#a48cbf}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}.card{background:white;padding:18px;border:1px solid #e1e5dc;border-radius:12px}.card-main{display:flex;gap:22px;text-align:left;width:100%;border:0;padding:0;background:none}.card-main img,.poster{width:115px;height:160px;object-fit:cover;border-radius:6px;flex-shrink:0}.poster{background:linear-gradient(145deg,#bdcbb4,#758d75);color:white;display:grid;place-content:center;text-align:center;font:20px Georgia;letter-spacing:3px}.badge{font-size:11px;background:#edf1e6;padding:4px 9px;border-radius:20px}.card h2{font-size:20px;margin:10px 0}.card p{font-size:12px;margin:5px 0}.card>button:last-child{margin-top:12px;font-size:12px}.overlay{position:fixed;inset:0;background:#16261f66;display:flex;align-items:center;justify-content:center;z-index:10;padding:24px}.dialog{position:relative;background:#fff;border-radius:14px;padding:32px;width:650px;max-height:90vh;overflow:auto;box-shadow:0 20px 80px #14271d44}.close{float:right}.hero{position:relative;clear:both}.hero img{width:100%;max-height:280px;object-fit:contain}.banner{background:#f0d9c9;padding:16px;margin:18px 0}.banner strong{display:block;font-size:18px}.banner span{font-size:15px}.announcement{background:#f3e8db;border-radius:8px;padding:15px;margin:15px 0}.announcement p{margin:7px 0}.platform{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}.platform img{height:16px;width:auto;max-width:70px;object-fit:contain}.editor label{display:flex;flex-direction:column;gap:5px;margin:12px 0}.editor .inline{display:inline-flex;flex-direction:row;margin-right:14px;align-items:center}.editor input[type=checkbox]{width:auto}.panel{border:1px solid #dce2d7;padding:15px;border-radius:8px;margin:15px 0}.panel input,.panel sele